command:
kill -9 1755 2>/dev/null; sleep 1; ss -tlnp | grep 8000; \
mkdir -p /etc/nginx/tls && cp /root/tls/node2.fullchain.pem /etc/nginx/tls/node2.fullchain.pem && cp /root/tls/node2.key.pem /etc/nginx/tls/node2.key.pem && \
chmod 600 /etc/nginx/tls/node2.key.pem && chmod 644 /etc/nginx/tls/node2.fullchain.pem && \
cat > /etc/nginx/sites-available/node2-tls <<'EOF'
server {
    listen 8443 ssl;
    server_name node2;

    ssl_certificate     /etc/nginx/tls/node2.fullchain.pem;
    ssl_certificate_key /etc/nginx/tls/node2.key.pem;
    ssl_protocols TLSv1.2 TLSv1.3;

    location / {
        return 200 "node2 HTTPS via Fleet Internal CA\n";
        add_header Content-Type text/plain;
    }
}
EOF
ln -sf /etc/nginx/sites-available/node2-tls /etc/nginx/sites-enabled/node2-tls && \
nginx -t

